define(["core/str"],function(str){let url="";let currentPage=0;let limit=0;let totalCourses=0;let blockInstanceId=0;function getElements(){return{courseArea:document.querySelector(".course-area"),searchInput:document.querySelector("#search"),pagination:document.querySelector(".pagination"),paginationNumbers:document.querySelector("#pagination-numbers"),prevPageButton:document.querySelector("#prev-page"),nextPageButton:document.querySelector("#next-page")}}async function loadCourses(){try{const{courseArea:courseArea,searchInput:searchInput}=getElements();if(!courseArea){return}const searchValue=searchInput?searchInput.value:"";const filters=getFilter();const queryParams=`page=${currentPage}&limit=${limit}`+`&blockinstanceid=${blockInstanceId}`+`&search=${encodeURIComponent(searchValue)}&workload=${filters.workload}`+`&certificate=${filters.certificate}&lang=${filters.lang}`+`&learningpath=${filters.learningpath}`;const response=await fetch(`${url}?${queryParams}`);if(!response.ok){console.error("Error fetching courses:",response.statusText);return}const data=await response.json();if(data.error){console.error("Error fetching courses:",data.error);return}const total=data.total||0;const courses=data.courses||[];const baseurl=data.baseurl||"";totalCourses=total;courseArea.innerHTML="";if(courses.length===0){const nomorecourses=await str.get_string("nomorecourses","core").catch(()=>"Nenhum curso encontrado");courseArea.innerHTML="<p>"+nomorecourses+"</p>";updatePaginationButtons();return}const certificateStr=await str.get_string("certificate","block_course_gallery").catch(()=>"Certificado");const workloadStr=await str.get_string("workload","block_course_gallery").catch(()=>"Carga horária");const hoursStr=await str.get_string("hours","block_course_gallery").catch(()=>"horas");const languageStr=await str.get_string("language","block_course_gallery").catch(()=>"Idioma");courses.forEach(course=>{const certificateArea=!course.has_certificate?"":`\n                    <div class="course-certificate">\n                        <p class="course-certificate-text">${certificateStr}</p>\n                        <span class="course-certificate-value">\n                            <img class="course-certificate-value-img"\n                                src="${baseurl}/theme/suap/pix/checkmark-circle-outline.svg" alt="">\n                        </span>\n                    </div>\n                `;const langArea=!course.lang?"":`\n                    <div class="course-lang">\n                        <p class="course-lang-text">${languageStr}</p>\n                        <span class="course-lang-value">${selectLangFlag(course.lang)}</span>\n                    </div>\n                `;const workloadArea=!course.workload?"":`\n                    <div class="course-workload">\n                        <p class="course-workload-text">${workloadStr}</p>\n                        <span class="course-workload-value">${course.workload+" "+hoursStr}</span>\n                    </div>\n                `;courseArea.innerHTML+=`\n                    <a class="course-gallery-card" id="${course.id}" href="${baseurl}/course/view.php?id=${course.id}">\n                        <div class="course-image-container">\n                            <img src="${course.image_url}" alt="${course.fullname}" class="course-image">\n                        </div>\n                        <span class="course-category">${course.category_name}</span>\n                        <span class="course-name">${course.fullname}</span>\n                        <div class="course-detail">\n                            ${workloadArea}\n                            ${certificateArea}\n                            ${langArea}\n                        </div>\n                    </a>\n                `});correctMainPadding();updatePaginationButtons()}catch(error){console.error("Error fetching courses:",error)}}function updatePaginationButtons(){paginationNumbers.innerHTML="";prevPageButton.disabled=currentPage===0;nextPageButton.disabled=(currentPage+1)*limit>=totalCourses;const totalPages=Math.ceil(totalCourses/limit);if(totalPages<=1){pagination.classList.add("disabled");return}const pageRange=2;let startPage=Math.max(0,currentPage-pageRange);let endPage=Math.min(totalPages-1,currentPage+pageRange);if(startPage>2){createPageButton(0);createPageButton(1);paginationNumbers.innerHTML+="... "}for(let i=startPage;i<=endPage;i++){createPageButton(i)}if(endPage<totalPages-3){paginationNumbers.innerHTML+=" ...";createPageButton(totalPages-2);createPageButton(totalPages-1)}nextPageButton.setAttribute("page",currentPage+1);prevPageButton.setAttribute("page",currentPage-1);pagination.classList.remove("disabled")}function createPageButton(page){const button=document.createElement("button");button.classList.add("pagination-number");button.textContent=page+1;if(page===currentPage){button.classList.add("active")}button.addEventListener("click",()=>{currentPage=page;loadCourses();updateActivePageButton()});paginationNumbers.appendChild(button)}function selectLangFlag(lang){switch(lang){case"pt_br":return"🇧🇷";case"en":return"🇺🇸";case"es":return"🇪🇸";default:return"🌐"}}function updateActivePageButton(){document.querySelectorAll(".pagination-number").forEach(button=>button.classList.remove("active"));const activeButton=document.querySelector(`.pagination-number:nth-child(${currentPage+1})`);if(activeButton){activeButton.classList.add("active")}}function getFilter(){const filters={workload:[],certificate:[],lang:[],learningpath:[]};const slider=document.getElementById("workload-slider");if(slider&&slider.noUiSlider){const values=slider.noUiSlider.get();const[minValue,maxValue]=values.map(Number);const range=slider.noUiSlider.options.range;const minPossible=range.min;const maxPossible=range.max;if(minValue===minPossible&&maxValue===maxPossible){filters.workload=[0]}else{filters.workload=[minValue,maxValue]}}filters.workload=filters.workload.join(",");document.querySelectorAll('#filter-content-certificate-column input[type="checkbox"]:checked').forEach(checkbox=>filters.certificate.push(checkbox.value));filters.certificate=filters.certificate.join(",");document.querySelectorAll('#filter-content-lang-column input[type="checkbox"]:checked').forEach(checkbox=>filters.lang.push(checkbox.value));filters.lang=filters.lang.join(",");document.querySelectorAll('#filter-content-learningpath-column input[type="checkbox"]:checked').forEach(checkbox=>filters.learningpath.push(checkbox.value));filters.learningpath=filters.learningpath.join(",");return filters}function updateFilterBadge(){const filters=getFilter();let totalFilters=0;if(filters.workload&&filters.workload!=="0"){totalFilters++}["certificate","lang","learningpath"].forEach(key=>{if(filters[key]){const values=filters[key].split(",").filter(Boolean);totalFilters+=values.length}});const badge=document.querySelector(".filter-badge");badge.style.display=totalFilters>0?"inline-block":"none";badge.innerHTML=totalFilters>0?totalFilters:""}function closeFilter(){document.querySelector("#filter-area").style.display="none";document.querySelector("#modal-overlay").style.display="none";toggleScroll()}function correctMainPadding(){const main=document.querySelector('[role="main"]');main.style.paddingLeft="0";main.style.paddingRight="0"}function toggleScroll(){const body=document.querySelector("body");if(body.style.overflow==="hidden"){body.style.overflow="auto"}else{body.style.overflow="hidden"}}const searchInput=document.querySelector("#search");if(searchInput){searchInput.addEventListener("input",loadCourses)}const prevPageButton=document.querySelector("#prev-page");if(prevPageButton){prevPageButton.addEventListener("click",()=>{if(currentPage>0){currentPage--;loadCourses()}})}const nextPageButton=document.querySelector("#next-page");if(nextPageButton){nextPageButton.addEventListener("click",()=>{if((currentPage+1)*limit<totalCourses){currentPage++;loadCourses()}})}const filterCourses=document.querySelector("#filter-courses");if(filterCourses){filterCourses.addEventListener("click",()=>{const filterArea=document.querySelector("#filter-area");const modalOverlay=document.querySelector("#modal-overlay");if(filterArea){filterArea.style.display="block"}if(modalOverlay){modalOverlay.style.display="block"}toggleScroll()})}const clearFilter=document.querySelector("#clear-filter");if(clearFilter){clearFilter.addEventListener("click",()=>{document.querySelectorAll('.filter-content input[type="checkbox"]').forEach(checkbox=>{checkbox.checked=false});const slider=document.getElementById("workload-slider");if(slider&&slider.noUiSlider){const range=slider.noUiSlider.options.range;slider.noUiSlider.set([range.min,range.max])}updateFilterBadge();currentPage=0;loadCourses()})}const applyFilter=document.querySelector("#apply-filter");if(applyFilter){applyFilter.addEventListener("click",()=>{currentPage=0;loadCourses();closeFilter();updateFilterBadge()})}const closeFilterBtn=document.querySelector("#close-filter");if(closeFilterBtn){closeFilterBtn.addEventListener("click",closeFilter)}const modalOverlay=document.querySelector("#modal-overlay");if(modalOverlay){modalOverlay.addEventListener("click",closeFilter)}window.addEventListener("load",correctMainPadding);return{init:(requestUrl,maxCourses,instanceId)=>{url=requestUrl;limit=maxCourses;limit=limit||9;blockInstanceId=instanceId||0;loadCourses()}}});